def area(shape: dict) -> float:
    """Return the area using match/case on the shape dict."""
    match shape:
        case {'type': 'circle', 'r': r}:
            return round(3.14159 * r * r, 2)
        case {'type': 'square', 'side': s}:
            return round(s * s, 2)
        case _:
            return 0.0

print(area({'type': 'circle', 'r': 2}))
